    form_value:=fauxlore.government_form(chosen);
    return jsonb_build_object('valid',true,'government_name',form_value);
  exception when sqlstate '22023' then
    return jsonb_build_object('valid',false,'error',sqlerrm);
  end;
end;
$$;
