          where sp.state_id in(proposal.from_state_id,proposal.to_state_id) and sp.is_npc
            and not exists(select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=sp.state_id)
        )
      ) recipient;
  end loop;
