  for fleet in select f.id,f.state_id,f.province_id,f.position_x,f.position_y,o.route,o.next_index
    from fauxlore.military_formations f left join fauxlore.military_movement_orders o on o.formation_id=f.id
    where f.active and f.domain='naval' loop
    if fleet.route is null then
      select * into start_port from fauxlore.military_accessible_port(fleet.state_id,fleet.province_id);
      if found then update fauxlore.military_formations set position_x=start_port.x,position_y=start_port.y where id=fleet.id; end if;
      continue;
    end if;
    route_value:=fleet.route; last_index:=jsonb_array_length(route_value)-1;
    if fleet.next_index=1 then
      select * into start_port from fauxlore.military_accessible_port(fleet.state_id,fleet.province_id);
      if found then
        update fauxlore.military_formations set position_x=start_port.x,position_y=start_port.y where id=fleet.id;
        route_value:=jsonb_set(route_value,'{0}',(route_value->0)||jsonb_build_object('x',start_port.x,'y',start_port.y),false);
