create or replace function fauxlore.military_upkeep_summary(target_state integer)
returns jsonb language plpgsql stable security definer set search_path='' as $function$
declare
  army_cost numeric:=0; fleet_cost numeric:=0; militia_cost numeric:=0;
  mercenary_cost numeric:=0; garrison_cost numeric:=0;
  militia_by_estate jsonb:=jsonb_build_object('Корона',0,'Знать',0,'Духовенство',0,'Горожане',0,'Крестьяне',0);
  garrison_by_estate jsonb; militia_row record; total_shares integer;
  burgher_cost integer; peasant_cost integer; noble_cost integer; crown_cost integer;
begin
  select coalesce(sum(cost) filter(where domain='land'),0),coalesce(sum(cost) filter(where domain='naval'),0)
    into army_cost,fleet_cost from (
      select f.id,f.domain,sum(u.upkeep*fauxlore.military_unit_cost_factor(target_state,u.id,'upkeep')*
        greatest(0,fu.quantity-case when u.name='Копейщик' then least(fu.quantity,coalesce(f.free_upkeep_quantity,0)) else 0 end)) cost
      from fauxlore.military_formations f join fauxlore.military_formation_units fu on fu.formation_id=f.id
      join fauxlore.military_unit_catalog u on u.id=fu.unit_id
      where f.state_id=target_state and f.active and f.kind='regular' group by f.id,f.domain
    ) formations;
  for militia_row in
    select mc.doctrine,mc.plan,
      floor(coalesce((select sum(fu.quantity::numeric*u.upkeep) from fauxlore.military_formation_units fu
        join fauxlore.military_unit_catalog u on u.id=fu.unit_id where fu.formation_id=mc.formation_id),0))::integer amount,
      floor(coalesce((select sum(fu.quantity::numeric*u.upkeep) from fauxlore.military_formation_units fu
        join fauxlore.military_unit_catalog u on u.id=fu.unit_id where fu.formation_id=mc.naval_formation_id),0))::integer naval_amount
    from fauxlore.militia_calls mc where mc.state_id=target_state and mc.status='active'
  loop
    militia_cost:=militia_cost+militia_row.amount+militia_row.naval_amount;
    burgher_cost:=0;peasant_cost:=0;noble_cost:=0;
    if militia_row.doctrine='Фирд' then
      total_shares:=coalesce((militia_row.plan#>>'{contributions,Горожане}')::integer,0)+
        coalesce((militia_row.plan#>>'{contributions,Крестьяне}')::integer,0);
      if total_shares>0 then
        burgher_cost:=floor(militia_row.amount*.6*coalesce((militia_row.plan#>>'{contributions,Горожане}')::integer,0)/total_shares);
        peasant_cost:=floor(militia_row.amount*.6*coalesce((militia_row.plan#>>'{contributions,Крестьяне}')::integer,0)/total_shares);
      end if;
    elsif militia_row.doctrine='Сословная армия' then noble_cost:=floor(militia_row.amount*.7); end if;
    crown_cost:=militia_row.amount+militia_row.naval_amount-burgher_cost-peasant_cost-noble_cost;
    militia_by_estate:=jsonb_set(militia_by_estate,'{Корона}',to_jsonb((militia_by_estate->>'Корона')::integer+crown_cost));
    militia_by_estate:=jsonb_set(militia_by_estate,'{Горожане}',to_jsonb((militia_by_estate->>'Горожане')::integer+burgher_cost));
    militia_by_estate:=jsonb_set(militia_by_estate,'{Крестьяне}',to_jsonb((militia_by_estate->>'Крестьяне')::integer+peasant_cost));
    militia_by_estate:=jsonb_set(militia_by_estate,'{Знать}',to_jsonb((militia_by_estate->>'Знать')::integer+noble_cost));
  end loop;
  select coalesce(sum(g.price*greatest(0,1+fauxlore.state_permanent_modifier_total(target_state,array['mercenary_upkeep'],null,null))),0)
    into mercenary_cost from fauxlore.military_formations f join fauxlore.mercenary_groups g on g.id=f.mercenary_group_id
    where f.state_id=target_state and f.active and f.kind='mercenary';
  garrison_cost:=fauxlore.garrison_upkeep(target_state);
  select coalesce(jsonb_object_agg(sponsor_estate,amount),'{}'::jsonb) into garrison_by_estate
    from (select g.sponsor_estate,sum(fauxlore.garrison_site_upkeep(g.province_id)) amount
      from fauxlore.garrison_sites g where g.state_id=target_state group by g.sponsor_estate) sponsored;
  return jsonb_build_object('army',army_cost,'fleet',fleet_cost,'militia',militia_cost,'mercenaries',mercenary_cost,
    'garrisons',garrison_cost,'garrison_by_estate',coalesce(garrison_by_estate,'{}'::jsonb),
    'militia_by_estate',militia_by_estate,'total',army_cost+fleet_cost+militia_cost+mercenary_cost+garrison_cost);
end
$function$;
revoke all on function fauxlore.military_upkeep_summary(integer) from public,anon,authenticated;
notify pgrst,'reload schema';

-- Applied migration: 20261030191500_militia_cost_projection.sql
-- Keep militia upkeep and estate funding forecasts on the server.
do $$
declare definition text; marker text; replacement text;
begin
  definition:=pg_get_functiondef('fauxlore.militia_preview(integer)'::regprocedure);
  definition:=replace(definition,
    '  unit_row record; unit_names text[]; shares numeric[];',
    '  unit_row record; unit_names text[]; shares numeric[]; land_upkeep integer:=0; naval_upkeep integer:=0; total_upkeep integer:=0; funding jsonb; burgher_cost integer:=0; peasant_cost integer:=0; noble_cost integer:=0; burgher_count integer:=0; peasant_count integer:=0;');
  marker:=$old$  return jsonb_build_object('doctrine',doctrine_value,'coefficient',coeff,'total',grand_total,$old$;
  replacement:=$new$  select floor(coalesce(sum((item.value)::integer*u.upkeep),0))::integer into land_upkeep
    from jsonb_each_text(units) item join fauxlore.military_unit_catalog u on u.name=item.key
    where u.state_id is null and u.active;
  select floor(coalesce(sum((fleet.value->>'cogs')::integer*u.upkeep),0))::integer into naval_upkeep
    from jsonb_array_elements(fauxlore.militia_cog_plan(state_key)) fleet(value)
    join fauxlore.military_unit_catalog u on u.name='Когг' and u.domain='naval' and u.state_id is null and u.active;
  total_upkeep:=land_upkeep+naval_upkeep;
  burgher_count:=coalesce((contributions->>'Горожане')::integer,0);
  peasant_count:=coalesce((contributions->>'Крестьяне')::integer,0);
  if doctrine_value='Фирд' and burgher_count+peasant_count>0 then
    burgher_cost:=floor(land_upkeep*.6*burgher_count/(burgher_count+peasant_count));
    peasant_cost:=floor(land_upkeep*.6*peasant_count/(burgher_count+peasant_count));
  elsif doctrine_value='Сословная армия' then
    noble_cost:=floor(land_upkeep*.7);
  end if;
  funding:=jsonb_build_object('Корона',total_upkeep-burgher_cost-peasant_cost-noble_cost,
    'Знать',noble_cost,'Духовенство',0,'Горожане',burgher_cost,'Крестьяне',peasant_cost);
  return jsonb_build_object('doctrine',doctrine_value,'coefficient',coeff,'total',grand_total,
    'upkeep',total_upkeep,'funding_by_estate',funding,
    'naval_crew_recruits',coalesce((select sum((fleet.value->>'crew_recruits')::integer)
      from jsonb_array_elements(fauxlore.militia_cog_plan(state_key)) fleet(value)),0),$new$;
  if position(marker in definition)=0 then raise exception 'Militia preview output marker not found'; end if;
  execute replace(definition,marker,replacement);
end $$;

